import asyncio
import json
from fastmcp import Server
from typing import Any
import inspect


def create_transparent_proxy(backend_server: Server) -> Server:
    """
    Create a transparent proxy FastMCP server forwarding all requests to a backend server.

    Args:
        backend_server: The backend FastMCP Server instance

    Returns:
        A new Server instance that proxies to the backend
    """
    proxy = Server("proxy")

    # Access backend's internal handler storage
    backend_tool_map = getattr(backend_server, '_tool_handlers', {})
    backend_resource_map = getattr(backend_server, '_resource_handlers', {})
    backend_prompt_map = getattr(backend_server, '_prompt_handlers', {})

    @proxy.list_tools()
    async def list_tools():
        """Forward tool listing to backend"""
        tools = []
        for name, tool_data in backend_tool_map.items():
            tools.append({
                "name": name,
                "description": tool_data.get("description", ""),
                "inputSchema": tool_data.get("input_schema", {})
            })
        return {"tools": tools}

    @proxy.call_tool()
    async def call_tool(name: str, arguments: dict) -> Any:
        """Forward tool calls to backend"""
        if name not in backend_tool_map:
            raise ValueError(f"Tool '{name}' not found")

        handler = backend_tool_map[name]["handler"]
        if inspect.iscoroutinefunction(handler):
            return await handler(**arguments)
        return handler(**arguments)

    @proxy.list_resources()
    async def list_resources():
        """Forward resource listing to backend"""
        resources = []
        for uri, resource_data in backend_resource_map.items():
            resources.append({
                "uri": uri,
                "name": resource_data.get("name", uri),
                "description": resource_data.get("description", ""),
                "mimeType": resource_data.get("mime_type", "text/plain")
            })
        return {"resources": resources}

    @proxy.read_resource()
    async def read_resource(uri: str) -> str:
        """Forward resource reads to backend"""
        if uri not in backend_resource_map:
            raise ValueError(f"Resource '{uri}' not found")

        handler = backend_resource_map[uri]["handler"]
        if inspect.iscoroutinefunction(handler):
            return await handler(uri)
        return handler(uri)

    if backend_prompt_map:
        @proxy.list_prompts()
        async def list_prompts():
            """Forward prompt listing to backend"""
            prompts = []
            for name, prompt_data in backend_prompt_map.items():
                prompts.append({
                    "name": name,
                    "description": prompt_data.get("description", ""),
                    "arguments": prompt_data.get("arguments", [])
                })
            return {"prompts": prompts}

        @proxy.get_prompt()
        async def get_prompt(name: str, arguments: dict) -> Any:
            """Forward prompt requests to backend"""
            if name not in backend_prompt_map:
                raise ValueError(f"Prompt '{name}' not found")

            handler = backend_prompt_map[name]["handler"]
            if inspect.iscoroutinefunction(handler):
                return await handler(**arguments)
            return handler(**arguments)

    return proxy


async def main():
    """Example: create backend server, then proxy it"""
    backend = Server("backend")

    @backend.call_tool()
    async def echo(message: str) -> str:
        return f"Echo: {message}"

    @backend.add_resource()
    def get_resource(uri: str) -> str:
        return f"Resource content from {uri}"

    proxy = create_transparent_proxy(backend)

    async with proxy:
        await proxy.wait_for_shutdown()


if __name__ == "__main__":
    asyncio.run(main())

